def test_init_width_zero():
    with pytest.raises(ValueError, match="dimensions must be positive"):
        Rectangle(0, 5)

def test_init_height_zero():
    with pytest.raises(ValueError, match="dimensions must be positive"):
        Rectangle(5, 0)

def test_init_both_zero():
    with pytest.raises(ValueError, match="dimensions must be positive"):
        Rectangle(0, 0)

def test_init_negative_width():
    with pytest.raises(ValueError, match="dimensions must be positive"):
        Rectangle(-1, 5)

def test_init_negative_height():
    with pytest.raises(ValueError, match="dimensions must be positive"):
        Rectangle(5, -1)

def test_init_negative_both():
    with pytest.raises(ValueError, match="dimensions must be positive"):
        Rectangle(-3, -4)

def test_area_positive():
    rect = Rectangle(3, 4)
    assert rect.area() == 12

def test_perimeter_positive():
    rect = Rectangle(3, 4)
    assert rect.perimeter() == 14
